def _canonical_existing_file(path: Path) -> Path:
    if "\n" in str(path) or "\r" in str(path):
        raise ValueError("path contains CR/LF")
    if not path.is_file() or path.is_symlink():
        raise ValueError(f"not a readable regular non-symlink file: {path}")
    return path.resolve()


def _heading_count(path: Path) -> int:
    return sum(1 for line in path.read_text(encoding="utf-8", errors="replace").splitlines() if re.match(r"^###[ \t]+(NEW|UPDATED|REWRITTEN)[ \t]*:", line))


def _extract_file_replacement(output: str) -> str:
    lines = output.splitlines()
    candidate: list[str] = []
    block: list[str] = []
    in_block = False
    trailer_idx = -1
    def capture() -> None:
        nonlocal candidate
        if trailer_idx < 0:
            return
        start = 0
        end = trailer_idx + 1
        local = block[start:end]
        if local and re.match(r"^```([A-Za-z0-9_-]+)?\s*$", local[0]):
            local = local[1:]
            if local and local[-1] == "```":
                local = local[:-1]
        candidate = local
    for line in lines:
        if line == "## Plan":
            if in_block:
                capture()
            in_block = True
            block = []
            trailer_idx = -1
        if in_block:
            block.append(line)
